        ],
        [
          1080,
          1305
        ]
      ]
    },
    {
      "id": "P3",
      "utc_offset": 60,
      "local_windows": [
        [
          840,
          1020
        ],
        [
          1080,
          1320
        ]
      ]
    },
    {
      "id": "P4",
      "utc_offset": 0,
      "local_windows": [
        [
          795,
          960
        ],
        [
          1020,
          1245
